//! Fixed-graph executor for the committed `microsalnet_v3ds_w24.onnx.gz`.
//!
//! `W24MicroModel::new()` decompresses the embedded ONNX via `zenflate`,
//! slices the 79 f32 weight tensors at the byte offsets recorded in
//! [`crate::w24_plan`] (generated by `tools/export_w24_nhwc.py`), transposes
//! them into the NHWC kernel layouts, and validates the 82-node plan. The
//! forward pass is then hand-scheduled over the same `archmage`/`magetypes`
//! kernels as the rest of the crate — no ONNX parser, no interpreter
//! dispatch, and zero heap allocation on a warm `W24Workspace`.

use alloc::vec::Vec;

use crate::kernels::{
    self, Activation, conv_transpose2x2_s2_cat_nhwc, conv_transpose2x2_s2_nhwc,
    conv1x1_head_sigmoid_nhwc, conv3x3_s2_nhwc, depthwise_conv3x3_nhwc, pointwise_conv1x1_nhwc,
    pointwise_conv1x1_residual_nhwc, se_gate_nhwc,
};
use crate::w24_plan::{self, idx};

/// Embedded model (compressed ONNX bytes, committed under zensally-tract).
const MODEL_GZ: &[u8] = include_bytes!("../../zensally-tract/models/microsalnet_v3ds_w24.onnx.gz");

/// One ONNX initializer's location inside the decompressed model bytes.
pub struct Weight {
    /// ONNX initializer name (e.g. `enc3.1.conv.6.fc2.weight`).
    pub name: &'static str,
    /// Tensor dims (`&'static` because the plan is a generated table).
    pub dims: &'static [usize],
    /// Byte offset of `raw_data` inside the decompressed model.
    pub offset: usize,
    /// `raw_data` byte length.
    pub bytes: usize,
}

/// ONNX operator subset the fixed graph uses (plan table only — execution
/// is hand-scheduled, so these validate rather than interpret).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Op {
    /// Dense or grouped conv; `groups` > 1 is depthwise here.
    Conv {
        /// Weight index into [`w24_plan::WEIGHTS`].
        w: usize,
        /// Bias index into [`w24_plan::WEIGHTS`].
        b: usize,
        /// Spatial stride.
        stride: usize,
        /// Pad on each side.
        pad: usize,
        /// Kernel dilation.
        dilation: usize,
        /// Group count (`== channels` => depthwise).
        groups: usize,
    },
    /// ConvTranspose 2x2 stride-2.
    Transpose {
        /// Weight index.
        w: usize,
        /// Bias index.
        b: usize,
        /// Spatial stride.
        stride: usize,
        /// Pad.
        pad: usize,
    },
    /// Elementwise ReLU.
    Relu,
    /// Elementwise logistic sigmoid.
    Sigmoid,
    /// Spatial global average pool (ReduceMean over NCHW axes 2,3).
    Mean,
    /// Elementwise add (residual).
    Add,
    /// Broadcast multiply (SE gate: `x * gate`).
    Mul,
    /// Channel concat (axis 1).
    Concat,
}

/// One node of the generated plan (output slot = its index + 1; slot 0 is
/// the model input).
pub struct Node {
    /// Input slot indices.
    pub inputs: &'static [usize],
    /// Operator + weight indices.
    pub op: Op,
}

/// Load/validation failure for [`W24MicroModel::new`].
#[derive(Debug)]
pub struct W24Error(pub &'static str);
impl core::fmt::Display for W24Error {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        f.write_str(self.0)
    }
}
#[cfg(feature = "std")]
impl std::error::Error for W24Error {}

/// Packed weights for one inverted-residual / dilated block:
/// `pw1` (expand 1x1) -> `dw` (3x3) -> `pw2` (project 1x1, optional residual).
struct Ir {
    pw1_w: Vec<f32>,
    pw1_b: Vec<f32>,
    dw_w: Vec<f32>,
    dw_b: Vec<f32>,
    pw2_w: Vec<f32>,
    pw2_b: Vec<f32>,
}

/// `Ir` plus squeeze-excitation weights (`fc1 C->mid`, `fc2 mid->C`, raw).
struct IrSe {
    ir: Ir,
    fc1_w: Vec<f32>,
    fc1_b: Vec<f32>,
    fc2_w: Vec<f32>,
    fc2_b: Vec<f32>,
}

/// The committed MicroSalNet v3ds w24 model with weights pre-packed into
/// NHWC kernel layouts. Construct once; `forward_nhwc` is `&self` and
/// allocation-free on a warm [`W24Workspace`].
pub struct W24MicroModel {
    stem_w: Vec<f32>,
    stem_b: Vec<f32>,
    enc10: Ir,
    enc11: Ir,
    enc20: Ir,
    enc21: Ir,
    enc30: IrSe,
    enc31: IrSe,
    /// Dilated bottleneck blocks, dilation 1, 2, 4, 8.
    bn: [Ir; 4],
    up3_w: Vec<f32>,
    up3_b: Vec<f32>,
    up2_w: Vec<f32>,
    up2_b: Vec<f32>,
    up1_w: Vec<f32>,
    up1_b: Vec<f32>,
    head_w: Vec<f32>,
    head_b: f32,
}

/// Pre-allocated feature-map scratch for one `forward_nhwc` call. All nine
/// buffers are sized for the fixed 256x256 input; reusing the workspace
/// across calls makes warm inference allocation-free.
pub struct W24Workspace {
    a: Vec<f32>,
    b: Vec<f32>,
    c: Vec<f32>,
    /// Residual carrier A/B: the five residual produces (enc3.1 + four
    /// bottleneck blocks) alternate `r -> r2 -> r -> ...`.
    r: Vec<f32>,
    r2: Vec<f32>,
    s0: Vec<f32>,
    s1: Vec<f32>,
    s2: Vec<f32>,
    d3: Vec<f32>,
}

impl W24Workspace {
    /// Allocate all stage buffers for the fixed 256x256 input.
    #[must_use]
    pub fn new() -> Self {
        let v = |n: usize| alloc::vec![0.0f32; n];
        Self {
            a: v(128 * 128 * 48),  // enc1.0 expand output (largest)
            b: v(64 * 64 * 48),    // dw outputs up to 64x64x48, d2 64x64x24
            c: v(128 * 128 * 24),  // SE outputs + d1 128x128x24
            r: v(64 * 64 * 24),    // block input / residual carrier A
            r2: v(16 * 16 * 72),   // residual carrier B (16x16x72 stages only)
            s0: v(128 * 128 * 24), // stem output
            s1: v(64 * 64 * 24),   // enc1 output
            s2: v(32 * 32 * 48),   // enc2 output
            d3: v(32 * 32 * 48),   // decoder stage d3 (kept for features)
        }
    }
    /// Total scratch bytes held by this workspace.
    #[must_use]
    pub fn byte_footprint(&self) -> usize {
        (self.a.len()
            + self.b.len()
            + self.c.len()
            + self.r.len()
            + self.r2.len()
            + self.s0.len()
            + self.s1.len()
            + self.s2.len()
            + self.d3.len())
            * 4
    }
}

impl Default for W24Workspace {
    fn default() -> Self {
        Self::new()
    }
}

/// Stride-8 (32x32) multi-task feature summary, extracted from a finished
/// forward pass at zero extra inference cost. Feeds `DualIntegralMap` crop
/// scoring without a second model run.
#[derive(Clone, Debug)]
pub struct W24Stride8Features {
    /// 4x4 box-average of the 128x128 saliency map, in `[0, 1]`.
    pub saliency_32x32: [f32; 32 * 32],
    /// Smooth foreground-subject matte: `saliency * semantic_energy`
    /// (per-cell product of the pooled saliency and the normalized d3
    /// bottleneck energy — both in `[0, 1]`, so the matte is too).
    pub matte_32x32: [f32; 32 * 32],
    /// Mean activation across d3's 48 channels per cell, divided by the
    /// map max so the hottest cell reads 1.0 (all-zero map stays 0).
    pub semantic_energy_32x32: [f32; 32 * 32],
}

/// Convenience alias matching the brief's naming.
pub type W24CropFeatures = W24Stride8Features;

fn read_f32s(bytes: &[u8], i: usize) -> Vec<f32> {
    let w = &w24_plan::WEIGHTS[i];
    bytes[w.offset..w.offset + w.bytes]
        .as_chunks::<4>()
        .0
        .iter()
        .map(|b| f32::from_le_bytes(*b))
        .collect()
}

/// OIHW `[o][i]` flat -> `[i][o]` raw layout for [`kernels::pack_pointwise_w`].
fn oi_to_io(w: &[f32], in_c: usize, out_c: usize) -> Vec<f32> {
    let mut out = alloc::vec![0.0f32; in_c * out_c];
    for o in 0..out_c {
        for i in 0..in_c {
            out[i * out_c + o] = w[o * in_c + i];
        }
    }
    out
}

impl W24MicroModel {
    /// Decompress the embedded model, validate the generated plan, and pack
    /// every weight into its NHWC kernel layout.
    pub fn new() -> Result<Self, W24Error> {
        let mut bytes = alloc::vec![0u8; w24_plan::MODEL_BYTES];
        let outcome = zenflate::Decompressor::new()
            .gzip_decompress(MODEL_GZ, &mut bytes, enough::Unstoppable)
            .map_err(|_| W24Error("embedded model gzip failed"))?;
        if outcome.output_written != bytes.len() {
            return Err(W24Error("truncated embedded model"));
        }
        Self::validate_plan()?;
        Ok(Self::load(&bytes))
    }

    /// The generated NODES table is load-bearing: it must describe exactly
    /// the 82-node graph the hand-scheduled forward implements.
    fn validate_plan() -> Result<(), W24Error> {
        let (mut conv, mut relu, mut sig, mut mean, mut add, mut mul, mut cat, mut tconv) =
            (0usize, 0, 0, 0, 0, 0, 0, 0);
        for node in w24_plan::NODES {
            match node.op {
                Op::Conv {
                    w,
                    b,
                    stride,
                    pad,
                    dilation,
                    groups,
                } => {
                    conv += 1;
                    let d = w24_plan::WEIGHTS[w].dims;
                    if d.len() != 4 || w24_plan::WEIGHTS[b].dims != [d[0]] {
                        return Err(W24Error("conv weight/bias dims"));
                    }
                    if groups > 1 && (groups != d[0] || d[1] != 1) {
                        return Err(W24Error("non-depthwise grouped conv"));
                    }
                    if d[2] == 3 && pad == 0 {
                        return Err(W24Error("3x3 conv without pad"));
                    }
                    let _ = (stride, dilation);
                }
                Op::Transpose { w, b, stride, pad } => {
                    tconv += 1;
                    let d = w24_plan::WEIGHTS[w].dims;
                    if d.len() != 4 || d[2] != 2 || d[3] != 2 || stride != 2 || pad != 0 {
                        return Err(W24Error("unsupported ConvTranspose"));
                    }
                    let _ = b;
                }
                Op::Relu => relu += 1,
                Op::Sigmoid => sig += 1,
                Op::Mean => mean += 1,
                Op::Add => add += 1,
                Op::Mul => mul += 1,
                Op::Concat => cat += 1,
            }
            for &i in node.inputs {
                if i > w24_plan::NODES.len() {
                    return Err(W24Error("input slot out of range"));
                }
            }
        }
        if (conv, relu, sig, mean, add, mul, cat, tconv) != (36, 26, 3, 2, 7, 2, 3, 3) {
            return Err(W24Error("unexpected op histogram"));
        }
        for w in w24_plan::WEIGHTS {
            if w.offset + w.bytes > w24_plan::MODEL_BYTES {
                return Err(W24Error("weight range out of model"));
            }
        }
        Ok(())
    }

    fn load(bytes: &[u8]) -> Self {
        let f = |i: usize| read_f32s(bytes, i);
        let pw = |wi: usize, bi: usize, ic: usize, oc: usize| {
            (
                kernels::pack_pointwise_w(&oi_to_io(&f(wi), ic, oc), ic, oc),
                f(bi),
            )
        };
        let ir = |pw1: (usize, usize, usize, usize),
                  dw: (usize, usize),
                  pw2: (usize, usize, usize, usize)| {
            let (pw1_w, pw1_b) = pw(pw1.0, pw1.1, pw1.2, pw1.3);
            let (pw2_w, pw2_b) = pw(pw2.0, pw2.1, pw2.2, pw2.3);
            let dc = w24_plan::WEIGHTS[dw.0].dims[0];
            Ir {
                pw1_w,
                pw1_b,
                dw_w: kernels::pack_depthwise_w(&f(dw.0), dc),
                dw_b: f(dw.1),
                pw2_w,
                pw2_b,
            }
        };
        use idx::*;
        Self {
            stem_w: kernels::pack_stem_w(&f(STEM_0_WEIGHT), 24),
            stem_b: f(STEM_0_WEIGHT_BIAS),
            enc10: ir(
                (ENC1_0_CONV_0_WEIGHT, ENC1_0_CONV_0_WEIGHT_BIAS, 24, 48),
                (ENC1_0_CONV_3_WEIGHT, ENC1_0_CONV_3_WEIGHT_BIAS),
                (ENC1_0_CONV_6_WEIGHT, ENC1_0_CONV_6_WEIGHT_BIAS, 48, 24),
            ),
            enc11: ir(
                (ENC1_1_CONV_0_WEIGHT, ENC1_1_CONV_0_WEIGHT_BIAS, 24, 48),
                (ENC1_1_CONV_3_WEIGHT, ENC1_1_CONV_3_WEIGHT_BIAS),
                (ENC1_1_CONV_6_WEIGHT, ENC1_1_CONV_6_WEIGHT_BIAS, 48, 24),
            ),
            enc20: ir(
                (ENC2_0_CONV_0_WEIGHT, ENC2_0_CONV_0_WEIGHT_BIAS, 24, 48),
                (ENC2_0_CONV_3_WEIGHT, ENC2_0_CONV_3_WEIGHT_BIAS),
                (ENC2_0_CONV_6_WEIGHT, ENC2_0_CONV_6_WEIGHT_BIAS, 48, 48),
            ),
            enc21: ir(
                (ENC2_1_CONV_0_WEIGHT, ENC2_1_CONV_0_WEIGHT_BIAS, 48, 96),
                (ENC2_1_CONV_3_WEIGHT, ENC2_1_CONV_3_WEIGHT_BIAS),
                (ENC2_1_CONV_6_WEIGHT, ENC2_1_CONV_6_WEIGHT_BIAS, 96, 48),
            ),
            enc30: IrSe {
                ir: ir(
                    (ENC3_0_CONV_0_WEIGHT, ENC3_0_CONV_0_WEIGHT_BIAS, 48, 96),
                    (ENC3_0_CONV_3_WEIGHT, ENC3_0_CONV_3_WEIGHT_BIAS),
                    (ENC3_0_CONV_7_WEIGHT, ENC3_0_CONV_7_WEIGHT_BIAS, 96, 72),
                ),
                fc1_w: f(ENC3_0_CONV_6_FC1_WEIGHT),
                fc1_b: f(ENC3_0_CONV_6_FC1_BIAS),
                fc2_w: f(ENC3_0_CONV_6_FC2_WEIGHT),
                fc2_b: f(ENC3_0_CONV_6_FC2_BIAS),
            },
            enc31: IrSe {
                ir: ir(
                    (ENC3_1_CONV_0_WEIGHT, ENC3_1_CONV_0_WEIGHT_BIAS, 72, 144),
                    (ENC3_1_CONV_3_WEIGHT, ENC3_1_CONV_3_WEIGHT_BIAS),
                    (ENC3_1_CONV_7_WEIGHT, ENC3_1_CONV_7_WEIGHT_BIAS, 144, 72),
                ),
                fc1_w: f(ENC3_1_CONV_6_FC1_WEIGHT),
                fc1_b: f(ENC3_1_CONV_6_FC1_BIAS),
                fc2_w: f(ENC3_1_CONV_6_FC2_WEIGHT),
                fc2_b: f(ENC3_1_CONV_6_FC2_BIAS),
            },
            bn: [
                ir(
                    (
                        BOTTLENECK_0_CONV_0_WEIGHT,
                        BOTTLENECK_0_CONV_0_WEIGHT_BIAS,
                        72,
                        144,
                    ),
                    (BOTTLENECK_0_CONV_3_WEIGHT, BOTTLENECK_0_CONV_3_WEIGHT_BIAS),
                    (
                        BOTTLENECK_0_CONV_6_WEIGHT,
                        BOTTLENECK_0_CONV_6_WEIGHT_BIAS,
                        144,
                        72,
                    ),
                ),
                ir(
                    (
                        BOTTLENECK_1_CONV_0_WEIGHT,
                        BOTTLENECK_1_CONV_0_WEIGHT_BIAS,
                        72,
                        144,
                    ),
                    (BOTTLENECK_1_CONV_3_WEIGHT, BOTTLENECK_1_CONV_3_WEIGHT_BIAS),
                    (
                        BOTTLENECK_1_CONV_6_WEIGHT,
                        BOTTLENECK_1_CONV_6_WEIGHT_BIAS,
                        144,
                        72,
                    ),
                ),
                ir(
                    (
                        BOTTLENECK_2_CONV_0_WEIGHT,
                        BOTTLENECK_2_CONV_0_WEIGHT_BIAS,
                        72,
                        144,
                    ),
                    (BOTTLENECK_2_CONV_3_WEIGHT, BOTTLENECK_2_CONV_3_WEIGHT_BIAS),
                    (
                        BOTTLENECK_2_CONV_6_WEIGHT,
                        BOTTLENECK_2_CONV_6_WEIGHT_BIAS,
                        144,
                        72,
                    ),
                ),
                ir(
                    (
                        BOTTLENECK_3_CONV_0_WEIGHT,
                        BOTTLENECK_3_CONV_0_WEIGHT_BIAS,
                        72,
                        144,
                    ),
                    (BOTTLENECK_3_CONV_3_WEIGHT, BOTTLENECK_3_CONV_3_WEIGHT_BIAS),
                    (
                        BOTTLENECK_3_CONV_6_WEIGHT,
                        BOTTLENECK_3_CONV_6_WEIGHT_BIAS,
                        144,
                        72,
                    ),
                ),
            ],
            up3_w: kernels::pack_tconv_w(&f(UP3_WEIGHT), 72, 48),
            up3_b: f(UP3_WEIGHT_BIAS),
            up2_w: kernels::pack_tconv_w(&f(UP2_WEIGHT), 96, 24),
            up2_b: f(UP2_WEIGHT_BIAS),
            up1_w: kernels::pack_tconv_w(&f(UP1_WEIGHT), 48, 24),
            up1_b: f(UP1_WEIGHT_BIAS),
            head_w: f(HEAD_WEIGHT),
            head_b: f(HEAD_BIAS)[0],
        }
    }

    /// Full forward pass: NHWC `256*256*3` f32 input in `[0, 1]` ->
    /// `128*128` saliency in `[0, 1]`. Performs no heap allocation on a warm
    /// `ws` (all stage buffers are preallocated there).
    pub fn forward_nhwc(
        &self,
        input_256x256x3: &[f32],
        ws: &mut W24Workspace,
        out_128x128: &mut [f32],
    ) {
        assert!(input_256x256x3.len() >= 256 * 256 * 3 && out_128x128.len() >= 128 * 128);
        let W24Workspace {
            a,
            b,
            c,
            r,
            r2,
            s0,
            s1,
            s2,
            d3,
        } = ws;
        use Activation::{Identity, ReLU};

        // stem: 256x256x3 -> 128x128x24 (s0)
        conv3x3_s2_nhwc::<24>(
            input_256x256x3,
            256,
            256,
            &self.stem_w,
            &self.stem_b,
            ReLU,
            s0,
        );

        // enc1.0: IR 24->24 s2 (no residual: stride 2)
        pointwise_conv1x1_nhwc::<24, 48>(
            s0,
            128 * 128,
            &self.enc10.pw1_w,
            &self.enc10.pw1_b,
            ReLU,
            a,
        );
        depthwise_conv3x3_nhwc::<48, 2, 1>(
            a,
            128,
            128,
            &self.enc10.dw_w,
            &self.enc10.dw_b,
            ReLU,
            b,
        );
        pointwise_conv1x1_nhwc::<48, 24>(
            b,
            64 * 64,
            &self.enc10.pw2_w,
            &self.enc10.pw2_b,
            Identity,
            r,
        );

        // enc1.1: IR 24->24 s1 residual -> s1 64x64x24
        pointwise_conv1x1_nhwc::<24, 48>(r, 64 * 64, &self.enc11.pw1_w, &self.enc11.pw1_b, ReLU, a);
        depthwise_conv3x3_nhwc::<48, 1, 1>(a, 64, 64, &self.enc11.dw_w, &self.enc11.dw_b, ReLU, b);
        pointwise_conv1x1_residual_nhwc::<48, 24>(
            b,
            64 * 64,
            &self.enc11.pw2_w,
            &self.enc11.pw2_b,
            r,
            Identity,
            s1,
        );

        // enc2.0: IR 24->48 s2
        pointwise_conv1x1_nhwc::<24, 48>(
            s1,
            64 * 64,
            &self.enc20.pw1_w,
            &self.enc20.pw1_b,
            ReLU,
            a,
        );
        depthwise_conv3x3_nhwc::<48, 2, 1>(a, 64, 64, &self.enc20.dw_w, &self.enc20.dw_b, ReLU, b);
        pointwise_conv1x1_nhwc::<48, 48>(
            b,
            32 * 32,
            &self.enc20.pw2_w,
            &self.enc20.pw2_b,
            Identity,
            r,
        );

        // enc2.1: IR 48->48 s1 residual -> s2 32x32x48
        pointwise_conv1x1_nhwc::<48, 96>(r, 32 * 32, &self.enc21.pw1_w, &self.enc21.pw1_b, ReLU, a);
        depthwise_conv3x3_nhwc::<96, 1, 1>(a, 32, 32, &self.enc21.dw_w, &self.enc21.dw_b, ReLU, b);
        pointwise_conv1x1_residual_nhwc::<96, 48>(
            b,
            32 * 32,
            &self.enc21.pw2_w,
            &self.enc21.pw2_b,
            r,
            Identity,
            s2,
        );

        // enc3.0: IR 48->72 s2 + SE(96, mid=24)
        pointwise_conv1x1_nhwc::<48, 96>(
            s2,
            32 * 32,
            &self.enc30.ir.pw1_w,
            &self.enc30.ir.pw1_b,
            ReLU,
            a,
        );
        depthwise_conv3x3_nhwc::<96, 2, 1>(
            a,
            32,
            32,
            &self.enc30.ir.dw_w,
            &self.enc30.ir.dw_b,
            ReLU,
            b,
        );
        se_gate_nhwc::<96, 24>(
            b,
            16,
            16,
            &self.enc30.fc1_w,
            &self.enc30.fc1_b,
            &self.enc30.fc2_w,
            &self.enc30.fc2_b,
            c,
        );
        pointwise_conv1x1_nhwc::<96, 72>(
            c,
            16 * 16,
            &self.enc30.ir.pw2_w,
            &self.enc30.ir.pw2_b,
            Identity,
            r,
        );

        // enc3.1: IR 72->72 s1 residual + SE(144, mid=36)
        pointwise_conv1x1_nhwc::<72, 144>(
            r,
            16 * 16,
            &self.enc31.ir.pw1_w,
            &self.enc31.ir.pw1_b,
            ReLU,
            a,
        );
        depthwise_conv3x3_nhwc::<144, 1, 1>(
            a,
            16,
            16,
            &self.enc31.ir.dw_w,
            &self.enc31.ir.dw_b,
            ReLU,
            b,
        );
        se_gate_nhwc::<144, 36>(
            b,
            16,
            16,
            &self.enc31.fc1_w,
            &self.enc31.fc1_b,
            &self.enc31.fc2_w,
            &self.enc31.fc2_b,
            c,
        );
        pointwise_conv1x1_residual_nhwc::<144, 72>(
            c,
            16 * 16,
            &self.enc31.ir.pw2_w,
            &self.enc31.ir.pw2_b,
            r,
            Identity,
            r2,
        );

        // bottleneck: 4x DilatedBlock(72, d = 1, 2, 4, 8), residual each.
        // The residual carrier alternates r2 -> r -> r2 -> r -> r2, so after
        // block 3 the state lives in r2.
        const DILS: [usize; 4] = [1, 2, 4, 8];
        for (i, &d) in DILS.iter().enumerate() {
            let blk = &self.bn[i];
            let (src, dst) = if i % 2 == 0 {
                (&*r2, &mut *r)
            } else {
                (&*r, &mut *r2)
            };
            pointwise_conv1x1_nhwc::<72, 144>(src, 16 * 16, &blk.pw1_w, &blk.pw1_b, ReLU, a);
            match d {
                1 => depthwise_conv3x3_nhwc::<144, 1, 1>(a, 16, 16, &blk.dw_w, &blk.dw_b, ReLU, b),
                2 => depthwise_conv3x3_nhwc::<144, 1, 2>(a, 16, 16, &blk.dw_w, &blk.dw_b, ReLU, b),
                4 => depthwise_conv3x3_nhwc::<144, 1, 4>(a, 16, 16, &blk.dw_w, &blk.dw_b, ReLU, b),
                _ => depthwise_conv3x3_nhwc::<144, 1, 8>(a, 16, 16, &blk.dw_w, &blk.dw_b, ReLU, b),
            }
            pointwise_conv1x1_residual_nhwc::<144, 72>(
                b,
                16 * 16,
                &blk.pw2_w,
                &blk.pw2_b,
                src,
                Identity,
                dst,
            );
        }

        // up3: ConvTranspose 72->48, 16x16 -> 32x32 -> d3 (state is in r2)
        conv_transpose2x2_s2_nhwc::<72, 48>(r2, 16, 16, &self.up3_w, &self.up3_b, ReLU, d3);
        // up2: cat(d3 48ch, s2 48ch) -> ConvTranspose 96->24 -> d2 in b
        conv_transpose2x2_s2_cat_nhwc::<48, 48, 24>(
            d3,
            s2,
            32,
            32,
            &self.up2_w,
            &self.up2_b,
            ReLU,
            b,
        );
        // up1: cat(d2 24ch, s1 24ch) -> ConvTranspose 48->24 -> d1 in c
        conv_transpose2x2_s2_cat_nhwc::<24, 24, 24>(
            b,
            s1,
            64,
            64,
            &self.up1_w,
            &self.up1_b,
            ReLU,
            c,
        );
        // head: cat(d1 24ch, s0 24ch) -> Conv1x1 48->1 + Sigmoid
        conv1x1_head_sigmoid_nhwc::<24, 24>(
            c,
            s0,
            128 * 128,
            &self.head_w,
            self.head_b,
            out_128x128,
        );
    }

    /// Extract the stride-8 feature summary after `forward_nhwc` has run on
    /// `ws`. `out_128x128` is the forward pass's output.
    pub fn extract_stride8_features(
        &self,
        ws: &W24Workspace,
        out_128x128: &[f32],
    ) -> W24Stride8Features {
        let mut f = W24Stride8Features {
            saliency_32x32: [0.0; 32 * 32],
            matte_32x32: [0.0; 32 * 32],
            semantic_energy_32x32: [0.0; 32 * 32],
        };
        // 4x4 box-pool of the saliency map.
        for y in 0..32usize {
            for x in 0..32usize {
                let mut s = 0.0f32;
                for dy in 0..4 {
                    for dx in 0..4 {
                        s += out_128x128[(y * 4 + dy) * 128 + x * 4 + dx];
                    }
                }
                f.saliency_32x32[y * 32 + x] = s * (1.0 / 16.0);
            }
        }
        // d3 semantic energy: mean over 48 channels, normalized by map max.
        let mut max_e = 0.0f32;
        for px in 0..32 * 32 {
            let mut s = 0.0f32;
            for ch in 0..48 {
                s += ws.d3[px * 48 + ch];
            }
            let e = s * (1.0 / 48.0);
            f.semantic_energy_32x32[px] = e;
            max_e = max_e.max(e);
        }
        if max_e > 0.0 {
            for e in &mut f.semantic_energy_32x32 {
                *e /= max_e;
            }
        }
        for i in 0..32 * 32 {
            f.matte_32x32[i] = f.saliency_32x32[i] * f.semantic_energy_32x32[i];
        }
        f
    }
}

/// Downsample a `512×384×3` NHWC RGB `[0, 1]` buffer (as produced by
/// [`zensally::stream_prep::preprocess_nhwc_strided`]) into a `256×256×3`
/// NHWC RGB `[0, 1]` buffer for [`W24MicroModel::forward_nhwc`].
///
/// Uses the exact 2:1 horizontal × 3:2 vertical pixel-center bilinear
/// weights (`3/8` and `1/8`), operating in a single linear streaming pass
/// over the 3-row × 2-column rational grid with zero heap allocation.
pub fn downsample_512x384_to_256x256_nhwc(src_512x384x3: &[f32], dst_256x256x3: &mut [f32]) {
    const SRC_ROW: usize = 512 * 3;
    const DST_ROW: usize = 256 * 3;
    assert!(
        src_512x384x3.len() >= 384 * SRC_ROW && dst_256x256x3.len() >= 256 * DST_ROW,
        "downsample_512x384_to_256x256_nhwc: buffer too small"
    );
    for g in 0..128usize {
        let r0 = &src_512x384x3[(3 * g) * SRC_ROW..(3 * g + 1) * SRC_ROW];
        let r1 = &src_512x384x3[(3 * g + 1) * SRC_ROW..(3 * g + 2) * SRC_ROW];
        let r2 = &src_512x384x3[(3 * g + 2) * SRC_ROW..(3 * g + 3) * SRC_ROW];
        let (d_top, d_rest) =
            dst_256x256x3[(2 * g) * DST_ROW..(2 * g + 2) * DST_ROW].split_at_mut(DST_ROW);
        let d_bot = &mut d_rest[..DST_ROW];
        for dx in 0..256usize {
            let s = dx * 6;
            let d = dx * 3;
            for c in 0..3usize {
                let p0 = r0[s + c] + r0[s + 3 + c];
                let p1 = r1[s + c] + r1[s + 3 + c];
                let p2 = r2[s + c] + r2[s + 3 + c];
                d_top[d + c] = 0.375 * p0 + 0.125 * p1;
                d_bot[d + c] = 0.125 * p1 + 0.375 * p2;
            }
        }
    }
}

/// Bilinearly stretch-resize `image` to a `256×256×3` NHWC RGB `[0, 1]`
/// buffer suitable for [`W24MicroModel::forward_nhwc`].
pub fn preprocess_image_256x256_nhwc(image: &zensally::ImageRef<'_>, dst_256x256x3: &mut [f32]) {
    const INPUT_SIZE: usize = 256;
    assert!(
        dst_256x256x3.len() >= 3 * INPUT_SIZE * INPUT_SIZE,
        "preprocess_image_256x256_nhwc: buffer too small"
    );
    let src_w = image.width;
    let src_h = image.height;
    if src_w == 0 || src_h == 0 {
        dst_256x256x3[..3 * INPUT_SIZE * INPUT_SIZE].fill(0.0);
        return;
    }
    let bpp = image.format.bytes_per_pixel();
    let (r_idx, g_idx, b_idx) = match image.format {
        zensally::PixelFormat::Bgra => (2, 1, 0),
        zensally::PixelFormat::Rgba | zensally::PixelFormat::Rgb => (0, 1, 2),
    };
    let x_ratio = (src_w as f32 - 1.0) / (INPUT_SIZE as f32 - 1.0);
    let y_ratio = (src_h as f32 - 1.0) / (INPUT_SIZE as f32 - 1.0);
    let src_stride = src_w as usize * bpp;
    let pixels = image.pixels;
    let inv255 = 1.0f32 / 255.0;

    for dst_y in 0..INPUT_SIZE {
        let src_yf = dst_y as f32 * y_ratio;
        let y0 = src_yf as usize;
        let y1 = (y0 + 1).min(src_h as usize - 1);
        let fy = src_yf - y0 as f32;
        let fy_inv = 1.0 - fy;

        for dst_x in 0..INPUT_SIZE {
            let src_xf = dst_x as f32 * x_ratio;
            let x0 = src_xf as usize;
            let x1 = (x0 + 1).min(src_w as usize - 1);
            let fx = src_xf - x0 as f32;
            let fx_inv = 1.0 - fx;

            let off00 = y0 * src_stride + x0 * bpp;
            let off10 = y0 * src_stride + x1 * bpp;
            let off01 = y1 * src_stride + x0 * bpp;
            let off11 = y1 * src_stride + x1 * bpp;

            let w00 = fx_inv * fy_inv;
            let w10 = fx * fy_inv;
            let w01 = fx_inv * fy;
            let w11 = fx * fy;

            let r = pixels[off00 + r_idx] as f32 * w00
                + pixels[off10 + r_idx] as f32 * w10
                + pixels[off01 + r_idx] as f32 * w01
                + pixels[off11 + r_idx] as f32 * w11;
            let g = pixels[off00 + g_idx] as f32 * w00
                + pixels[off10 + g_idx] as f32 * w10
                + pixels[off01 + g_idx] as f32 * w01
                + pixels[off11 + g_idx] as f32 * w11;
            let b = pixels[off00 + b_idx] as f32 * w00
                + pixels[off10 + b_idx] as f32 * w10
                + pixels[off01 + b_idx] as f32 * w01
                + pixels[off11 + b_idx] as f32 * w11;

            let dst_off = (dst_y * INPUT_SIZE + dst_x) * 3;
            dst_256x256x3[dst_off] = r * inv255;
            dst_256x256x3[dst_off + 1] = g * inv255;
            dst_256x256x3[dst_off + 2] = b * inv255;
        }
    }
}

/// Target dimensions for [`MicroCropAnalyzer`]: 512×384 pixels over a
/// stride-8 64×48 feature grid (matching the v0.2 corpus evaluation).
const TARGET_W: usize = 512;
const TARGET_H: usize = 384;
const GRID_W: usize = TARGET_W / 8;
const GRID_H: usize = TARGET_H / 8;

/// Dependency-free (`tract-onnx`-free) v0.2 fast crop analyzer backed by
/// [`W24MicroModel`], [`zensally::stream_prep`], and [`zensally::sat_crop`].
///
/// Runs the complete single-pass v0.2 fast pipeline with zero per-call heap
/// allocations inside inference and preprocessing:
/// 1. `stream_prep::preprocess_nhwc_strided` stretches the image to `512×384`
///    NHWC while computing the `64×48` classical energy map and `48`-row
///    horizon profile (`~1.5 ms`).
/// 2. [`downsample_512x384_to_256x256_nhwc`] resamples the normalized `512×384`
///    NHWC buffer into `256×256` NHWC in L2 cache (`~0.04 ms`).
/// 3. [`W24MicroModel::forward_nhwc`] computes the `128×128` saliency map and
///    [`W24MicroModel::extract_stride8_features`] derives the `32×32`
///    foreground matte from the `d3` decoder bottleneck at zero extra model
///    cost (`~3.3 ms`).
/// 4. [`zensally::sat_crop::DualIntegralMap::from_crop_inputs`] fuses all
///    channels into a reusable summed-area table for `O(1)`-per-candidate
///    multi-aspect crop solving (`~0.4 ms` for 8 aspect/mode pairs, `~5.2 ms`
///    end-to-end).
pub struct MicroCropAnalyzer {
    model: W24MicroModel,
    ws: W24Workspace,
    nhwc: Vec<f32>,
    nhwc_256: Vec<f32>,
    sal_map: zensally::SaliencyMap,
    matte_map: zensally::SaliencyMap,
    classical: Vec<f32>,
    horizon: Vec<f32>,
    scratch: Vec<f32>,
    prep_cfg: zensally::preprocess::PreprocessConfig,
}

impl MicroCropAnalyzer {
    /// Load the embedded MicroSalNet v3ds-w24 model into [`W24MicroModel`] and
    /// pre-allocate all preprocessing and inference workspaces.
    pub fn new() -> Result<Self, W24Error> {
        use zensally::preprocess::{Normalization, ResizeMode};
        Ok(Self {
            model: W24MicroModel::new()?,
            ws: W24Workspace::new(),
            nhwc: alloc::vec![0.0; 3 * TARGET_W * TARGET_H],
            nhwc_256: alloc::vec![0.0; 3 * 256 * 256],
            sal_map: zensally::SaliencyMap {
                data: alloc::vec![0.0; 128 * 128],
                width: 128,
                height: 128,
            },
            matte_map: zensally::SaliencyMap {
                data: alloc::vec![0.0; 32 * 32],
                width: 32,
                height: 32,
            },
            classical: alloc::vec![0.0; GRID_W * GRID_H],
            horizon: alloc::vec![0.0; GRID_H],
            scratch: alloc::vec![
                0.0;
                zensally::stream_prep::prep_scratch_len(TARGET_W, GRID_W, GRID_H)
            ],
            prep_cfg: zensally::preprocess::PreprocessConfig {
                target_w: TARGET_W,
                target_h: TARGET_H,
                mode: ResizeMode::Stretch,
                norm: Normalization::UnitScale,
            },
        })
    }

    /// Run fused `stream_prep` + [`W24MicroModel`] inference and build a
    /// reusable [`zensally::sat_crop::DualIntegralMap`] without face detections.
    pub fn build_integral_map(
        &mut self,
        image: &zensally::ImageRef<'_>,
        manual_focus: &[zensally::FocusRegion],
    ) -> (
        zensally::sat_crop::DualIntegralMap,
        zensally::sat_crop::TargetToSrc,
    ) {
        self.build_integral_map_with_faces(image, &[], manual_focus)
    }

    /// Run fused `stream_prep` + [`W24MicroModel`] inference and build a
    /// reusable [`zensally::sat_crop::DualIntegralMap`] fused with caller-supplied
    /// `faces` and `manual_focus` regions.
    pub fn build_integral_map_with_faces(
        &mut self,
        image: &zensally::ImageRef<'_>,
        faces: &[zensally::sat_crop::FaceLandmarkInput],
        manual_focus: &[zensally::FocusRegion],
    ) -> (
        zensally::sat_crop::DualIntegralMap,
        zensally::sat_crop::TargetToSrc,
    ) {
        use zensally::sat_crop::{CropInputSources, DualIntegralMap, TargetToSrc};
        use zensally::stream_prep::{self, PrepOutputs};

        let mut outputs = PrepOutputs {
            output_nhwc: &mut self.nhwc,
            classical_energy: &mut self.classical,
            horizon_profile: &mut self.horizon,
            scratch: &mut self.scratch,
        };
        stream_prep::preprocess_nhwc_strided(
            image.pixels,
            image.width,
            image.height,
            image.width as usize * image.format.bytes_per_pixel(),
            image.format,
            &self.prep_cfg,
            &mut outputs,
        );

        downsample_512x384_to_256x256_nhwc(&self.nhwc, &mut self.nhwc_256);
        self.model
            .forward_nhwc(&self.nhwc_256, &mut self.ws, &mut self.sal_map.data);
        let f8 = self
            .model
            .extract_stride8_features(&self.ws, &self.sal_map.data);
        self.matte_map.data.copy_from_slice(&f8.matte_32x32);

        let to_src =
            TargetToSrc::stretch(image.width, image.height, TARGET_W as u32, TARGET_H as u32);
        let sources = CropInputSources {
            saliency: Some(&self.sal_map),
            matte: Some(&self.matte_map),
            faces,
            manual_focus,
            classical_energy: Some(&self.classical),
            horizon_profile: Some(&self.horizon),
        };
        (
            DualIntegralMap::from_crop_inputs(&sources, GRID_W, GRID_H, &to_src, 0.25),
            to_src,
        )
    }

    /// Run fused `stream_prep` + [`W24MicroModel`] inference and return a
    /// serializable, resolution-independent [`zensally::CropMetadata`] for
    /// free future crop derivation.
    pub fn extract_metadata(
        &mut self,
        image: &zensally::ImageRef<'_>,
        manual_focus: &[zensally::FocusRegion],
    ) -> zensally::CropMetadata {
        self.extract_metadata_with_faces(image, &[], manual_focus)
    }

    /// Run fused `stream_prep` + [`W24MicroModel`] inference and return a
    /// serializable, resolution-independent [`zensally::CropMetadata`] fused
    /// with caller-supplied `faces` and `manual_focus` regions.
    pub fn extract_metadata_with_faces(
        &mut self,
        image: &zensally::ImageRef<'_>,
        faces: &[zensally::sat_crop::FaceLandmarkInput],
        manual_focus: &[zensally::FocusRegion],
    ) -> zensally::CropMetadata {
        use zensally::sat_crop::{CropInputSources, TargetToSrc};
        use zensally::stream_prep::{self, PrepOutputs};

        let mut outputs = PrepOutputs {
            output_nhwc: &mut self.nhwc,
            classical_energy: &mut self.classical,
            horizon_profile: &mut self.horizon,
            scratch: &mut self.scratch,
        };
        stream_prep::preprocess_nhwc_strided(
            image.pixels,
            image.width,
            image.height,
            image.width as usize * image.format.bytes_per_pixel(),
            image.format,
            &self.prep_cfg,
            &mut outputs,
        );

        downsample_512x384_to_256x256_nhwc(&self.nhwc, &mut self.nhwc_256);
        self.model
            .forward_nhwc(&self.nhwc_256, &mut self.ws, &mut self.sal_map.data);
        let f8 = self
            .model
            .extract_stride8_features(&self.ws, &self.sal_map.data);
        self.matte_map.data.copy_from_slice(&f8.matte_32x32);

        let to_src =
            TargetToSrc::stretch(image.width, image.height, TARGET_W as u32, TARGET_H as u32);
        let sources = CropInputSources {
            saliency: Some(&self.sal_map),
            matte: Some(&self.matte_map),
            faces,
            manual_focus,
            classical_energy: Some(&self.classical),
            horizon_profile: Some(&self.horizon),
        };
        zensally::CropMetadata::from_crop_inputs(
            &sources,
            GRID_W,
            GRID_H,
            &to_src,
            0.25,
            Some("zensally-micro/0.2.0"),
        )
    }

    /// Analyze the image and solve one `(aspect, mode)` crop.
    pub fn compute_crop(
        &mut self,
        image: &zensally::ImageRef<'_>,
        target_aspect: (u32, u32),
        mode: zensally::sat_crop::SatCropMode,
        manual_focus: &[zensally::FocusRegion],
    ) -> Option<zensally::CropRect> {
        let (map, to_src) = self.build_integral_map(image, manual_focus);
        zensally::sat_crop::solve_crop_sat(
            &map,
            &to_src,
            target_aspect,
            mode,
            &zensally::sat_crop::SatCropConfig::default(),
        )
    }

    /// Analyze the image once, then solve every `(aspect, mode)` request
    /// against the shared integral map.
    pub fn compute_crops(
        &mut self,
        image: &zensally::ImageRef<'_>,
        requests: &[((u32, u32), zensally::sat_crop::SatCropMode)],
        manual_focus: &[zensally::FocusRegion],
    ) -> Vec<Option<zensally::CropRect>> {
        let (map, to_src) = self.build_integral_map(image, manual_focus);
        zensally::sat_crop::solve_crops_sat(
            &map,
            &to_src,
            requests,
            &zensally::sat_crop::SatCropConfig::default(),
        )
    }
}
